const stacks=[['.NET','C# · .sln · .csproj'],['Web','React · Next.js · Vue · Angular'],['Mobile','Flutter · Dart'],['Python','pyproject.toml · requirements.txt'],['Rust & Go','Cargo.toml · go.mod'],['Java','Maven · Gradle'],['Native','CMake'],['Infrastructure','Docker Compose']];
const initialText=new Map([...document.querySelectorAll('[data-t]')].map(n=>[n,n.innerHTML]));
const languageButton=document.getElementById('language');
const menuButton=document.getElementById('menu-toggle');
const navigation=document.getElementById('navigation');
let language='tr';
let selected=0;
try{const saved=localStorage.getItem('devworkspace-site-language');if(saved==='en')language='en';}catch{}
// Escape content before inserting it into templates. Only bundled translations contain markup.
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderPanel(){
 const item=content[language].features[selected];
 const panel=document.getElementById('feature-panel');
 panel.setAttribute('aria-labelledby',`feature-tab-${selected}`);
 panel.innerHTML=`<div><span class="panel-tag">${esc(item[1])}</span><h3>${esc(item[2])}</h3><p>${esc(item[3])}</p></div><ul class="panel-list">${item[4].map(s=>`<li><span class="check" aria-hidden="true">✓</span>${esc(s)}</li>`).join('')}</ul>`;
 document.querySelectorAll('[role="tab"]').forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===selected));tab.tabIndex=i===selected?0:-1;});
}
function selectTab(index,focus=false){selected=index;renderPanel();if(focus)document.getElementById(`feature-tab-${index}`).focus();}
function closeMenu(){navigation.classList.remove('is-open');menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label',language==='tr'?'Menüyü aç':'Open menu');}
function render(){
 document.documentElement.lang=language;
 const en=language==='en';
 document.title=en?'DevWorkspace — Many projects. One workspace.':'DevWorkspace — Çok proje. Tek çalışma alanı.';
 const description=en?'Discover projects, review Git changes, start your development environment and manage releases. A connected developer workspace for Windows.':'Projelerinizi keşfedin, Git değişikliklerini inceleyin, geliştirme ortamınızı başlatın ve sürümlerinizi yönetin. Windows için bütünleşik geliştirici çalışma alanı.';
 document.querySelector('meta[name="description"]').content=description;
 document.querySelector('meta[property="og:title"]').content=document.title;
 document.querySelector('meta[property="og:description"]').content=description;
 initialText.forEach((original,node)=>{node.innerHTML=en?english[node.dataset.t]:original;});
 languageButton.textContent=en?'TR':'EN';languageButton.setAttribute('aria-label',en?'Türkçeye geç':'Switch to English');
 navigation.setAttribute('aria-label',en?'Main navigation':'Ana menü');
 document.querySelector('.feature-tabs').setAttribute('aria-label',en?'Capability categories':'Yetenek kategorileri');
 document.querySelector('.orbit').setAttribute('aria-label',en?'Conceptual diagram connecting projects, Git, tools and releases':'Proje, Git, araç ve sürüm akışlarını bir araya getiren kavramsal şema');
 const data=content[language];
 document.querySelector('.feature-tabs').innerHTML=data.features.map((f,i)=>`<button type="button" role="tab" id="feature-tab-${i}" aria-controls="feature-panel" aria-selected="${i===selected}" tabindex="${i===selected?0:-1}">${esc(f[0])}</button>`).join('');
 document.querySelectorAll('[role="tab"]').forEach((tab,i)=>{
  tab.addEventListener('click',()=>selectTab(i));
  tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%data.features.length;if(e.key==='ArrowLeft')next=(i+data.features.length-1)%data.features.length;if(e.key==='Home')next=0;if(e.key==='End')next=data.features.length-1;if(next!==undefined){e.preventDefault();selectTab(next,true);}});
 });
 renderPanel();
 document.getElementById('feature-grid').innerHTML=data.cards.map((c,i)=>`<article class="feature-card"><span class="card-num">0${i+1} /</span><h3>${esc(c[0])}</h3><p>${esc(c[1])}</p></article>`).join('');
 document.getElementById('workflow-steps').innerHTML=data.steps.map((s,i)=>`<article class="workflow-step"><span>0${i+1}</span><h3>${esc(s[0])}</h3><p>${esc(s[1])}</p></article>`).join('');
 document.getElementById('scenarios').innerHTML=data.scenarios.map(s=>`<article class="scenario"><span>${esc(s[0])}</span><h3>${esc(s[1])}</h3><p>${esc(s[2])}</p><ul>${s[3].map(t=>`<li>${esc(t)}</li>`).join('')}</ul></article>`).join('');
 document.getElementById('stack-grid').innerHTML=stacks.map(s=>`<div class="stack-item"><strong>${esc(s[0])}</strong><span>${esc(s[1])}</span></div>`).join('');
 document.getElementById('trust-facts').innerHTML=data.trust.map(s=>`<article><h3>${esc(s[0])}</h3><p>${esc(s[1])}</p></article>`).join('');
 document.getElementById('resource-grid').innerHTML=data.resources.map(s=>`<a class="resource-card" href="${esc(s[3])}"><span>${esc(s[0])}</span><h3>${esc(s[1])}</h3><p>${esc(s[2])}</p><span class="resource-arrow" aria-hidden="true">↗</span></a>`).join('');
 document.getElementById('faq').innerHTML=data.faq.map(s=>`<details><summary>${esc(s[0])}</summary><p>${esc(s[1])}</p></details>`).join('');
 closeMenu();
}
languageButton.addEventListener('click',()=>{language=language==='tr'?'en':'tr';try{localStorage.setItem('devworkspace-site-language',language);}catch{}render();});
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';navigation.classList.toggle('is-open',open);menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',language==='tr'?(open?'Menüyü kapat':'Menüyü aç'):(open?'Close menu':'Open menu'));});
navigation.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menuButton.getAttribute('aria-expanded')==='true'){closeMenu();menuButton.focus();}});
document.addEventListener('click',e=>{if(!e.target.closest('.header'))closeMenu();});
render();
